// MountCLI returns a fresh, unattached Cobra root command. Most command paths
// are native Cobra commands; legacy compatibility remains for the default
// prompt path and explicitly delegated commands.
func MountCLI(opts ...MountOption) *cobra.Command {
	cfg := mountConfig{
		use:    productinfo.BinaryName,
		short:  "Run the fiz CLI",
		stdin:  os.Stdin,
		stdout: os.Stdout,
		stderr: os.Stderr,
	}
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}
	if cfg.version != "" {
		Version = cfg.version
	}
	if cfg.buildTime != "" {
		BuildTime = cfg.buildTime
	}
	if cfg.gitCommit != "" {
		GitCommit = cfg.gitCommit
	}
	cmd := &cobra.Command{
		Use:           cfg.use,
		Short:         cfg.short,
		Long:          cfg.long,
		SilenceUsage:  true,
		SilenceErrors: true,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runMounted(cfg, legacyArgs(cmd, args...))
		},
	}
	addLegacyPersistentFlags(cmd)
	addMountedSubcommands(cmd, cfg)
	cmd.SetIn(cfg.stdin)
	cmd.SetOut(cfg.stdout)
	cmd.SetErr(cfg.stderr)
	return cmd
