func TestResolveRouteModelConstraintNormalization(t *testing.T) {
	t.Setenv("PATH", "")
	cacheDir := t.TempDir()
	t.Setenv("FIZEAU_CACHE_DIR", cacheDir)
	cases := []struct {
		name      string
