430	func resolveModel(models []modelregistry.KnownModel, ref string) (modelregistry.KnownModel, error) {
431		ref = strings.TrimSpace(ref)
432		if strings.Contains(ref, "/") {
433			provider, id, ok := strings.Cut(ref, "/")
434			if !ok || provider == "" || id == "" {
435				return modelregistry.KnownModel{}, fmt.Errorf("invalid model %q", ref)
436			}
437			for _, model := range models {
438				if model.Provider == provider && model.ID == id {
439					return model, nil
440				}
441			}
442			return modelregistry.KnownModel{}, fmt.Errorf("unknown model %q", ref)
443		}
444	
445		var matches []modelregistry.KnownModel
446		lower := strings.ToLower(ref)
447		for _, model := range models {
448			id := strings.ToLower(model.ID)
449			if id == lower || strings.Contains(id, lower) {
450				matches = append(matches, model)
451			}
452		}
453		sort.Slice(matches, func(i, j int) bool { return canonicalModelID(matches[i]) < canonicalModelID(matches[j]) })
454		switch len(matches) {
455		case 0:
456			return modelregistry.KnownModel{}, fmt.Errorf("no model matched %q\n%s", ref, formatModelSuggestions(models, ref))
457		case 1:
458			return matches[0], nil
459		default:
460			return modelregistry.KnownModel{}, fmt.Errorf("ambiguous model %q\nCandidates:\n%s", ref, formatModelCandidates(matches))
461		}
462	}
