486	func summarizeModelsFreshness(snapshot modelregistry.ModelSnapshot) modelsSnapshotFreshness {
487		summary := modelsSnapshotFreshness{State: "fresh"}
488		for name, meta := range snapshot.Sources {
489			stale := meta.Stale || strings.TrimSpace(meta.Error) != ""
490			if !stale {
491				continue
492			}
493			summary.AnyStale = true
494			if strings.HasSuffix(name, ":props") {
495				continue
496			}
497			summary.RoutingStale = true
498			if strings.Contains(strings.ToLower(meta.Error), "refresh_failed") {
499				summary.RefreshFailed = true
500			}
501		}
502		if summary.RefreshFailed {
503			summary.State = "refresh_failed"
504		} else if summary.AnyStale {
505			summary.State = "stale"
506		}
507		if summary.RoutingStale {
508			summary.Hint = "run fiz models --refresh or start/configure a DDx server freshness heartbeat"
509		}
510		return summary
511	}
